[{"order":1,"type":"heading","text":"Custom Hooks: Extracting Component Logic in React"},{"order":2,"type":"paragraph","text":"React Hooks have revolutionized how we manage state and side effects in functional components. Custom Hooks take this a step further by allowing you to extract component logic into reusable functions. This promotes cleaner, more maintainable, and testable code. This tutorial will guide you through creating and using custom hooks effectively."},{"order":3,"type":"subheading","text":"What are Custom Hooks?"},{"order":4,"type":"paragraph","text":"Custom Hooks are JavaScript functions whose names start with 'use' and that may call other Hooks. They allow you to extract stateful logic from a component so that it can be tested independently and reused. Essentially, they are a mechanism for reusing stateful logic, not state itself. Each component using a custom hook gets its own isolated state."},{"order":5,"type":"subheading","text":"Why Use Custom Hooks?"},{"order":6,"type":"bullet_point","text":"Code Reusability: Avoid duplicating logic across multiple components."},{"order":7,"type":"bullet_point","text":"Improved Readability: Makes components cleaner and easier to understand by extracting complex logic."},{"order":8,"type":"bullet_point","text":"Enhanced Testability: Allows you to test the extracted logic in isolation."},{"order":9,"type":"bullet_point","text":"Separation of Concerns: Promotes a better separation of concerns within your application."},{"order":10,"type":"subheading","text":"Creating a Custom Hook: useCounter Example"},{"order":11,"type":"paragraph","text":"Let's create a simple custom hook called `useCounter` that manages a counter state and provides functions to increment, decrement, and reset the counter."},{"order":12,"type":"code","text":"import { useState } from 'react';

function useCounter(initialValue = 0) {
  const [count, setCount] = useState(initialValue);

  const increment = () => {
    setCount(count + 1);
  };

  const decrement = () => {
    setCount(count - 1);
  };

  const reset = () => {
    setCount(initialValue);
  };

  return {
    count,
    increment,
    decrement,
    reset,
  };
}

export default useCounter;"},{"order":13,"type":"paragraph","text":"Explanation:"},{"order":14,"type":"bullet_point","text":"We import the `useState` hook from React."},{"order":15,"type":"bullet_point","text":"The `useCounter` function takes an optional `initialValue` argument, defaulting to 0."},{"order":16,"type":"bullet_point","text":"We use `useState` to create a `count` state variable and a `setCount` function to update it."},{"order":17,"type":"bullet_point","text":"We define `increment`, `decrement`, and `reset` functions that update the `count` state."},{"order":18,"type":"bullet_point","text":"The hook returns an object containing the `count` state and the functions to manipulate it."},{"order":19,"type":"subheading","text":"Using the Custom Hook in a Component"},{"order":20,"type":"paragraph","text":"Now, let's use the `useCounter` hook in a React component."},{"order":21,"type":"code","text":"import React from 'react';
import useCounter from './useCounter';

function CounterComponent() {
  const { count, increment, decrement, reset } = useCounter(10); // Initial value of 10

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={increment}>Increment</button>
      <button onClick={decrement}>Decrement</button>
      <button onClick={reset}>Reset</button>
    </div>
  );
}

export default CounterComponent;"},{"order":22,"type":"paragraph","text":"Explanation:"},{"order":23,"type":"bullet_point","text":"We import the `useCounter` hook."},{"order":24,"type":"bullet_point","text":"We call the `useCounter` hook inside the `CounterComponent` and destructure the returned object to get the `count`, `increment`, `decrement`, and `reset` values."},{"order":25,"type":"bullet_point","text":"We use these values to display the counter and attach the functions to button click handlers."},{"order":26,"type":"subheading","text":"Another Example: useFetch"},{"order":27,"type":"paragraph","text":"Let's create a more complex custom hook called `useFetch` that handles fetching data from an API."},{"order":28,"type":"code","text":"import { useState, useEffect } from 'react';

function useFetch(url) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch(url);
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const json = await response.json();
        setData(json);
      } catch (error) {
        setError(error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [url]); // Dependency array ensures the effect runs only when the URL changes

  return { data, loading, error };
}

export default useFetch;"},{"order":29,"type":"paragraph","text":"Explanation:"},{"order":30,"type":"bullet_point","text":"We import `useState` and `useEffect` from React."},{"order":31,"type":"bullet_point","text":"The `useFetch` function takes a `url` as an argument."},{"order":32,"type":"bullet_point","text":"We use `useState` to create `data`, `loading`, and `error` state variables."},{"order":33,"type":"bullet_point","text":"We use `useEffect` to fetch data when the component mounts or when the `url` changes."},{"order":34,"type":"bullet_point","text":"Inside the `useEffect`, we define an `async` function `fetchData` that fetches the data from the API."},{"order":35,"type":"bullet_point","text":"We handle potential errors using a `try...catch` block."},{"order":36,"type":"bullet_point","text":"We set the `loading` state to `false` in the `finally` block, regardless of whether the fetch was successful or not."},{"order":37,"type":"bullet_point","text":"The hook returns an object containing the `data`, `loading`, and `error` states."},{"order":38,"type":"subheading","text":"Using the useFetch Hook"},{"order":39,"type":"code","text":"import React from 'react';
import useFetch from './useFetch';

function DataComponent() {
  const { data, loading, error } = useFetch('https://jsonplaceholder.typicode.com/todos/1');

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error: {error.message}</p>;
  if (!data) return <p>No data to display...</p>;

  return (
    <div>
      <h1>{data.title}</h1>
      <p>Completed: {data.completed ? 'Yes' : 'No'}</p>
    </div>
  );
}

export default DataComponent;"},{"order":40,"type":"paragraph","text":"Explanation:"},{"order":41,"type":"bullet_point","text":"We import the `useFetch` hook."},{"order":42,"type":"bullet_point","text":"We call the `useFetch` hook inside the `DataComponent` and destructure the returned object to get the `data`, `loading`, and `error` values."},{"order":43,"type":"bullet_point","text":"We use conditional rendering to display a loading message, an error message, or the data, depending on the state of `loading` and `error`."},{"order":44,"type":"subheading","text":"Rules of Hooks"},{"order":45,"type":"paragraph","text":"Custom Hooks, like built-in Hooks, must follow the Rules of Hooks:"},{"order":46,"type":"bullet_point","text":"Only Call Hooks at the Top Level: Don’t call Hooks inside loops, conditions, or nested functions."},{"order":47,"type":"bullet_point","text":"Only Call Hooks from React Functions: Call them from within React function components or from within other custom Hooks."},{"order":48,"type":"subheading","text":"Conclusion"},{"order":49,"type":"paragraph","text":"Custom Hooks are a powerful tool for extracting and reusing component logic in React. By following the Rules of Hooks and designing your hooks carefully, you can create cleaner, more maintainable, and testable React applications. They promote code reuse, improve readability, and enhance testability, making them an essential part of modern React development."}]
